CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "displayName" TEXT NOT NULL, "avatar" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Group" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "GroupMember" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'MEMBER', CONSTRAINT "GroupMember_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "Group" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "GroupMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "GroupMember_groupId_userId_key" ON "GroupMember"("groupId", "userId");
CREATE TABLE "Room" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "name" TEXT NOT NULL, "mode" TEXT NOT NULL DEFAULT 'watch', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Room_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "Group" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "QueueItem" ("id" TEXT NOT NULL PRIMARY KEY, "roomId" TEXT NOT NULL, "addedById" TEXT NOT NULL, "provider" TEXT NOT NULL, "providerMediaId" TEXT NOT NULL, "title" TEXT NOT NULL, "thumbnail" TEXT, "duration" REAL, "addedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QueueItem_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "QueueItem_addedById_fkey" FOREIGN KEY ("addedById") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ChatMessage" ("id" TEXT NOT NULL PRIMARY KEY, "roomId" TEXT NOT NULL, "userId" TEXT NOT NULL, "body" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ChatMessage_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ChatMessage_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "MediaHistory" ("id" TEXT NOT NULL PRIMARY KEY, "roomId" TEXT NOT NULL, "addedById" TEXT NOT NULL, "provider" TEXT NOT NULL, "providerMediaId" TEXT NOT NULL, "title" TEXT NOT NULL, "thumbnail" TEXT, "duration" REAL, "playedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MediaHistory_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "MediaHistory_addedById_fkey" FOREIGN KEY ("addedById") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
